@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare - Home</PageTitle>

<h1>🍳 RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/recipes/@category.Name.ToLower()" class="category-card">
            <span class="category-icon">@category.Icon</span>
            <h3>@category.Name</h3>
            <p>@category.Description</p>
        </a>
    }
</div>

<div class="submit-cta">
    <h2>Have a recipe to share?</h2>
    <a href="/submit" class="btn-submit">Submit a Recipe</a>
</div>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }
}

