arguments.file_text:
@page "/recipes/{Category}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>
<p><a href="/">← Back to categories</a></p>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <div class="recipe-card">
                <h3><a href="/recipes/@Category.ToLower()/@recipe.Id">@recipe.Title</a></h3>
                <div class="rating-display">
                    @for (int i = 1; i <= 5; i++)
                    {
                        <span class="@(i <= Math.Round(recipe.AverageRating) ? "star filled" : "star")">★</span>
                    }
                    <span class="rating-text">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipes/{Category}/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
    <a href="/">← Back to home</a>
}
else
{
    <p><a href="/recipes/@Category.ToLower()">← Back to @Category recipes</a></p>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>

        <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" @rendermode="InteractiveServer" />

        <section class="ingredients">
            <h2>🥘 Ingredients</h2>
            <ul>
                @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="steps">
            <h2>📝 Steps</h2>
            @foreach (var step in Recipe.Steps.Split('\n'))
            {
                <p>@step</p>
            }
        </section>
    </article>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Parameter] public int Id { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var starValue = i;
        <span class="@GetStarClass(starValue)" @onclick="() => Rate(starValue)" @onmouseover="() => hoverStar = starValue" @onmouseout="() => hoverStar = 0">★</span>
    }
    <span class="rating-text">@CurrentRating / 5 (@RatingCount ratings)</span>
    @if (userRating > 0)
    {
        <span class="user-rating-text">You rated: @userRating ★</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int hoverStar;
    private int userRating;

    private string GetStarClass(int star)
    {
        if (hoverStar > 0)
            return star <= hoverStar ? "star hover" : "star";
        return star <= Math.Round(CurrentRating) ? "star filled" : "star";
    }

    private void Rate(int stars)
    {
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Recipe submitted successfully!</h2>
        <p>Thank you for sharing "<strong>@model.Title</strong>" with the community.</p>
        <a href="/">← Back to home</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="model.Ingredients" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => model.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="model.Steps" rows="8" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
            <ValidationMessage For="() => model.Steps" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private RecipeFormModel model = new();
    private bool submitted;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };
        RecipeService.AddRecipe(recipe);
        submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3-100 characters")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category")]
        public string Category { get; set; } = string.Empty;

