html {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    line-height: 1.6;
    color: #333;
}

body {
    max-width: 900px;
    margin: 0 auto;
    padding: 1rem 2rem;
    background: #fafafa;
}

h1 { color: #2c3e50; }
a { color: #e67e22; text-decoration: none; }
a:hover { text-decoration: underline; }

.lead { font-size: 1.2rem; color: #555; }

/* Category grid */
.category-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 1.5rem;
    margin: 2rem 0;
}

.category-card {
    display: block;
    background: white;
    border-radius: 12px;
    padding: 1.5rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    transition: transform 0.2s, box-shadow 0.2s;
    text-decoration: none !important;
    color: inherit;
}

.category-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 4px 16px rgba(0,0,0,0.12);
}

.category-icon { font-size: 2.5rem; }
.category-card h3 { margin: 0.5rem 0 0.25rem; color: #2c3e50; }
.category-card p { margin: 0; color: #666; font-size: 0.9rem; }

/* Recipe list */
.recipe-list { margin: 1.5rem 0; }

.recipe-card {
    background: white;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}

.recipe-card h3 { margin: 0 0 0.5rem; }

/* Star rating */
.star-rating { margin: 1rem 0; }

.star {
    font-size: 1.5rem;
    color: #ddd;
    cursor: pointer;
    transition: color 0.15s;
}

.star.filled { color: #f39c12; }
.star.hover { color: #e67e22; }
.rating-display .star { cursor: default; font-size: 1.2rem; }
.rating-text { color: #666; font-size: 0.9rem; margin-left: 0.5rem; }
.user-rating-text { color: #27ae60; font-size: 0.85rem; margin-left: 1rem; font-style: italic; }

/* Recipe detail */
.recipe-detail { margin: 1rem 0; }
.recipe-detail h2 { margin-top: 2rem; color: #2c3e50; }
.ingredients ul { list-style: disc; padding-left: 1.5rem; }
.ingredients li { margin-bottom: 0.3rem; }

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.4rem;
    color: #2c3e50;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea { resize: vertical; }

.btn-submit {
    display: inline-block;
    background: #e67e22;
    color: white;
    padding: 0.75rem 2rem;
    border: none;
    border-radius: 8px;
    font-size: 1.05rem;
    cursor: pointer;
    text-decoration: none;
    transition: background 0.2s;
}

.btn-submit:hover { background: #d35400; color: white; }

.submit-cta {
    margin-top: 3rem;
    padding: 2rem;
    background: white;
    border-radius: 12px;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.success-message {
    background: #d4edda;
    border: 1px solid #c3e6cb;
    border-radius: 8px;
    padding: 2rem;
    margin: 1rem 0;
}

.validation-message { color: #e74c3c; font-size: 0.85rem; }

/* Navigation */
nav { margin-bottom: 2rem; padding-bottom: 1rem; border-bottom: 1px solid #eee; }
nav a { margin-right: 1.5rem; font-weight: 500; }

